    @Test
    public void testGetDateTimeInstance_DifferentStyles() {
        TimeZone tz = TimeZone.getDefault();
        Locale loc = Locale.US;

        FastDateFormat style1 = FastDateFormat.getDateTimeInstance(Calendar.SHORT, Calendar.SHORT, tz, loc);
